  "src/components/FilterOptions.jsx": "import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { setFilters, performSearch } from '../features/filteredSearchResults/slice';

const FilterOptions = () => {
  const dispatch = useDispatch();
  const filters = useSelector((state) => state.filteredSearchResults.filters);

  const handleFilterChange = (e) => {
    const { name, value, type, checked } = e.target;
    let newFilterValue = value;

    if (name === 'priceRange') {
      const [min, max] = value.split('-').map(Number);
      newFilterValue = [min, max];
    } else if (type === 'checkbox') {
      newFilterValue = checked ? value : ''; // Simple toggle for single selection
    }

    dispatch(setFilters({ [name]: newFilterValue }));
    dispatch(performSearch());
  };

  return (
    <div className="bg-white p-4 rounded-lg shadow-md mb-6">
      <h3 className="text-lg font-semibold mb-3">Filter Artworks</h3>

      <div className="mb-4">
        <label htmlFor="artistFilter" className="block text-sm font-medium text-gray-700">Artist:</label>
        <input
          type="text"
          id="artistFilter"
          name="artist"
          value={filters.artist}
          onChange={handleFilterChange}
          className="mt-1 block w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
