  "src/components/CartSummary.jsx": "import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { removeItem, updateQuantity } from '../features/cartContents/slice';
import { Link } from 'react-router-dom';

const CartSummary = () => {
  const dispatch = useDispatch();
  const cartItems = useSelector((state) => state.cartContents.items);

  const handleRemoveItem = (cartItemId) => {
    dispatch(removeItem(cartItemId));
  };

  const handleQuantityChange = (cartItemId, newQuantity) => {
    if (newQuantity < 1) return;
    dispatch(updateQuantity({ cartItemId, quantity: newQuantity }));
  };

  const calculateTotal = () => {
    return cartItems.reduce((total, item) => total + item.price * item.quantity, 0).toFixed(2);
  };

  if (cartItems.length === 0) {
    return (
      <div className="bg-white p-6 rounded-lg shadow-md text-center">
        <p className="text-gray-600">Your cart is empty.</p>
        <Link to="/gallery" className="mt-4 inline-block bg-indigo-600 text-white py-2 px-4 rounded-md hover:bg-indigo-700 transition duration-300">
          Explore Gallery
        </Link>
      </div>
    );
  }

  return (
    <div className="bg-white p-6 rounded-lg shadow-md">
      <h2 className="text-2xl font-bold mb-4">Your Cart</h2>
      <div className="space-y-4">
        {cartItems.map((item) => (
          <div key={item.cartItemId} className="flex items-center border-b pb-4 last:border-b-0 last:pb-0">
            <img src={item.imageUrl} alt={item.title} className="w-20 h-20 object-cover rounded-md mr-4" />
            <div className="flex-1">
              <h3 className="font-semibold text-lg">{item.title}</h3>
              <p className="text-gray-600 text-sm">by {item.artist}</p>
              <p className="text-indigo-700 font-bold">${item.price.toFixed(2)}</p>
            </div>
            <div className="flex items-center space-x-2">
              <button
                onClick={() => handleQuantityChange(item.cartItemId, item.quantity - 1)}
                className="bg-gray-200 text-gray-700 px-3 py-1 rounded-md hover:bg-gray-300"
              >
                -
              </button>
              <span className="text-lg font-medium">{item.quantity}</span>
              <button
                onClick={() => handleQuantityChange(item.cartItemId, item.quantity + 1)}
                className="bg-gray-200 text-gray-700 px-3 py-1 rounded-md hover:bg-gray-300"
              >
                +
              </button>
            </div>
            <button
              onClick={() => handleRemoveItem(item.cartItemId)}
              className="ml-4 text-red-600 hover:text-red-800 transition duration-300"
            >
              Remove
            </button>
          </div>
        ))}
      </div>
      <div className="mt-6 pt-4 border-t border-gray-200 flex justify-between items-center">
        <span className="text-xl font-bold">Total:</span>
        <span className="text-2xl font-bold text-indigo-800">${calculateTotal()}</span>
      </div>
      <Link to="/checkout" className="mt-6 block text-center bg-green-600 text-white py-3 rounded-md hover:bg-green-700 transition duration-300 text-lg font-semibold">
        Proceed to Checkout
      </Link>
    </div>
  );
};

export default CartSummary;",
