import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  selectedArtwork: null,
  loading: false,
  error: null,
};

export const artworkDetailsSlice = createSlice({
  name: 'artworkDetails',
  initialState,
  reducers: {
    setSelectedArtwork: (state, action) => {
      state.selectedArtwork = action.payload;
      state.loading = false;
      state.error = null;
    },
    clearSelectedArtwork: (state) => {
      state.selectedArtwork = null;
      state.loading = false;
      state.error = null;
    },
    setLoading: (state, action) => {
      state.loading = action.payload;
    },
    setError: (state, action) => {
      state.error = action.payload;
      state.loading = false;
    },
  },
});

export const { setSelectedArtwork, clearSelectedArtwork, setLoading, setError } = artworkDetailsSlice.actions;

export default artworkDetailsSlice.reducer;

