import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  searchTerm: '',
  filters: {
    artist: '',
    medium: '',
    priceRange: [0, 10000],
  },
  results: [],
  loading: false,
  error: null,
};

export const filteredSearchResultsSlice = createSlice({
  name: 'filteredSearchResults',
  initialState,
  reducers: {
    setSearchTerm: (state, action) => {
      state.searchTerm = action.payload;
    },
    setFilters: (state, action) => {
      state.filters = { ...state.filters, ...action.payload };
    },
    setResults: (state, action) => {
      state.results = action.payload;
      state.loading = false;
      state.error = null;
    },
    setLoading: (state, action) => {
      state.loading = action.payload;
    },
    setError: (state, action) => {
      state.error = action.payload;
      state.loading = false;
    },
    // Mock search logic for demonstration
    performSearch: (state) => {
      state.loading = true;
      state.error = null;
      const mockArtworks = [
        { id: 'a1', title: 'Sunset over Mountains', artist: 'Jane Doe', medium: 'Oil', price: 500, imageUrl: 'https://via.placeholder.com/150/FF7F50/FFFFFF?text=Artwork1' },
        { id: 'a2', title: 'Abstract Cityscape', artist: 'John Smith', medium: 'Acrylic', price: 1200, imageUrl: 'https://via.placeholder.com/150/6495ED/FFFFFF?text=Artwork2' },
        { id: 'a3', title: 'Portrait of a Lady', artist: 'Jane Doe', medium: 'Charcoal', price: 300, imageUrl: 'https://via.placeholder.com/150/DAA520/FFFFFF?text=Artwork3' },
        { id: 'a4', title: 'Vibrant Still Life', artist: 'Alice Brown', medium: 'Oil', price: 800, imageUrl: 'https://via.placeholder.com/150/FFD700/FFFFFF?text=Artwork4' },
        { id: 'a5', title: 'Mystical Forest', artist: 'John Smith', medium: 'Watercolor', price: 250, imageUrl: 'https://via.placeholder.com/150/8FBC8F/FFFFFF?text=Artwork5' },
        { id: 'h1', title: 'Galactic Horizon', artist: 'Alex Rivers', medium: 'Digital Art', price: 750, imageUrl: 'https://via.placeholder.com/150/4B0082/FFFFFF?text=Galactic+Horizon' },
        { id: 'h2', title: 'Silent Bloom', artist: 'Maria Chen', medium: 'Oil', price: 920, imageUrl: 'https://via.placeholder.com/150/8A2BE2/FFFFFF?text=Silent+Bloom' },
        { id: 'h3', title: 'Urban Echoes', artist: 'David Kim', medium: 'Mixed Media', price: 680, imageUrl: 'https://via.placeholder.com/150/9370DB/FFFFFF?text=Urban+Echoes' }
      ];

      const filtered = mockArtworks.filter(artwork => {
        const matchesSearchTerm = 
          artwork.title.toLowerCase().includes(state.searchTerm.toLowerCase()) ||
          artwork.artist.toLowerCase().includes(state.searchTerm.toLowerCase()) ||
          artwork.medium.toLowerCase().includes(state.searchTerm.toLowerCase());

        const matchesArtist = !state.filters.artist || artwork.artist.toLowerCase().includes(state.filters.artist.toLowerCase());
        const matchesMedium = !state.filters.medium || artwork.medium.toLowerCase() === state.filters.medium.toLowerCase();
        const matchesPrice = artwork.price >= state.filters.priceRange[0] && artwork.price <= state.filters.priceRange[1];

        return matchesSearchTerm && matchesArtist && matchesMedium && matchesPrice;
      });

      state.results = filtered;
      state.loading = false;
    },
  },
});

export const { setSearchTerm, setFilters, setResults, setLoading, setError, performSearch } = filteredSearchResultsSlice.actions;

export default filteredSearchResultsSlice.reducer;

