import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useLocation } from 'react-router-dom';
import SearchBar from '../components/SearchBar';
import FilterOptions from '../components/FilterOptions';
import ArtworkCard from '../components/ArtworkCard';
import { performSearch, setFilters } from '../features/filteredSearchResults/slice';

const Gallery = () => {
  const dispatch = useDispatch();
  const { results, loading, error } = useSelector((state) => state.filteredSearchResults);
  const location = useLocation();

  useEffect(() => {
    const queryParams = new URLSearchParams(location.search);
    const artistFilter = queryParams.get('artist');

    if (artistFilter) {
      dispatch(setFilters({ artist: artistFilter }));
    } else {
      // Clear artist filter if no query param, to avoid persistence across navigations
      dispatch(setFilters({ artist: '' }));
    }
    dispatch(performSearch()); // Perform search with (potentially updated) filters
  }, [dispatch, location.search]);

  if (loading) {
    return <div className="container mx-auto p-8 text-center text-lg">Loading artworks...</div>;
  }

  if (error) {
    return <div className="container mx-auto p-8 text-center text-red-600 text-lg">Error: {error}</div>;
  }

  return (
    <div className="container mx-auto p-8">
      <h1 className="text-4xl font-bold text-indigo-800 mb-8 text-center">Our Gallery</h1>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
        <div className="md:col-span-1">
          <SearchBar />
          <FilterOptions />
        </div>
        <div className="md:col-span-3">
          {results.length === 0 ? (
            <p className="text-center text-gray-600 text-lg">No artworks found matching your criteria.</p>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {results.map((artwork) => (
                <ArtworkCard key={artwork.id} artwork={artwork} />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Gallery;

