import { createSlice } from '@reduxjs/toolkit';
import { v4 as uuidv4 } from 'uuid';

const initialState = {
  items: [],
};

export const cartContentsSlice = createSlice({
  name: 'cartContents',
  initialState,
  reducers: {
    addItem: (state, action) => {
      const { id, title, artist, price, imageUrl } = action.payload;
      const existingItem = state.items.find((item) => item.artworkId === id);
      if (existingItem) {
        existingItem.quantity += 1;
      } else {
        state.items.push({
          cartItemId: uuidv4(),
          artworkId: id,
          title,
          artist,
          price,
          imageUrl,
          quantity: 1,
        });
      }
    },
    removeItem: (state, action) => {
      state.items = state.items.filter((item) => item.cartItemId !== action.payload);
    },
    updateQuantity: (state, action) => {
      const { cartItemId, quantity } = action.payload;
      const item = state.items.find((item) => item.cartItemId === cartItemId);
      if (item) {
        item.quantity = quantity;
      }
    },
    clearCart: (state) => {
      state.items = [];
    },
  },
});

export const { addItem, removeItem, updateQuantity, clearCart } = cartContentsSlice.actions;

export default cartContentsSlice.reducer;

