import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { setSelectedArtwork, clearSelectedArtwork, setLoading, setError } from '../features/artworkDetails/slice';
import { addItem } from '../features/cartContents/slice';
import ReviewForm from '../components/ReviewForm';
import { v4 as uuidv4 } from 'uuid';

// Mock data for artworks and reviews
const mockArtworks = [
  { id: 'a1', title: 'Sunset over Mountains', artist: 'Jane Doe', medium: 'Oil', price: 500, description: 'A vibrant oil painting capturing the serene beauty of a mountain sunset.', imageUrl: 'https://via.placeholder.com/600x400/FF7F50/FFFFFF?text=Artwork1' },
  { id: 'a2', title: 'Abstract Cityscape', artist: 'John Smith', medium: 'Acrylic', price: 1200, description: 'Dynamic and colorful abstract representation of urban life.', imageUrl: 'https://via.placeholder.com/600x400/6495ED/FFFFFF?text=Artwork2' },
  { id: 'a3', title: 'Portrait of a Lady', artist: 'Jane Doe', medium: 'Charcoal', price: 300, description: 'An expressive charcoal drawing showcasing subtle human emotions.', imageUrl: 'https://via.placeholder.com/600x400/DAA520/FFFFFF?text=Artwork3' },
  { id: 'h1', title: 'Galactic Horizon', artist: 'Alex Rivers', medium: 'Digital Art', price: 750, description: 'A breathtaking digital painting depicting a cosmic landscape with a distant galaxy.', imageUrl: 'https://via.placeholder.com/600x400/4B0082/FFFFFF?text=Galactic+Horizon' },
  { id: 'h2', title: 'Silent Bloom', artist: 'Maria Chen', medium: 'Oil', price: 920, description: 'A peaceful oil painting of blooming flowers, evoking tranquility.', imageUrl: 'https://via.placeholder.com/600x400/8A2BE2/FFFFFF?text=Silent+Bloom' },
  { id: 'h3', title: 'Urban Echoes', artist: 'David Kim', medium: 'Mixed Media', price: 680, description: 'An intricate mixed media piece exploring the sounds and sights of city life.', imageUrl: 'https://via.placeholder.com/600x400/9370DB/FFFFFF?text=Urban+Echoes' },
];

const ArtworkDetails = () => {
  const { artworkId } = useParams();
  const dispatch = useDispatch();
  const { selectedArtwork, loading, error } = useSelector((state) => state.artworkDetails);
  const [reviews, setReviews] = useState([
    { id: uuidv4(), author: 'Art Lover', rating: 5, comment: 'Absolutely stunning! The colors are so vivid.', date: '2023-01-15' },
    { id: uuidv4(), author: 'Gallery Enthusiast', rating: 4, comment: 'A captivating piece. I particularly enjoyed the brushwork.', date: '2023-03-20' },
  ]);

  useEffect(() => {
    // Simulate fetching artwork details
    dispatch(setLoading(true));
    const artwork = mockArtworks.find(art => art.id === artworkId);
    if (artwork) {
      dispatch(setSelectedArtwork(artwork));
    } else {
      dispatch(setError('Artwork not found.'));
    }
    dispatch(setLoading(false));

    return () => {
      dispatch(clearSelectedArtwork());
    };
  }, [artworkId, dispatch]);

  const handleAddToCart = () => {
    if (selectedArtwork) {
      dispatch(addItem(selectedArtwork));
      alert(`${selectedArtwork.title} added to cart!`);
    }
  };

  const handleReviewSubmit = (newReview) => {
    setReviews((prevReviews) => [...prevReviews, newReview]);
    alert('Review submitted successfully!');
  };

  if (loading) {
    return <div className="container mx-auto p-8 text-center text-lg">Loading artwork details...</div>;
  }

  if (error) {
    return <div className="container mx-auto p-8 text-center text-red-600 text-lg">Error: {error}</div>;
  }

  if (!selectedArtwork) {
    return <div className="container mx-auto p-8 text-center text-lg">Select an artwork to view details.</div>;
  }

  const averageRating = reviews.length > 0 
    ? (reviews.reduce((sum, review) => sum + review.rating, 0) / reviews.length).toFixed(1) 
    : 'N/A';

  return (
    <div className="container mx-auto p-8">
      <div className="bg-white rounded-lg shadow-lg overflow-hidden md:flex">
        <div className="md:w-1/2">
          <img 
            src={selectedArtwork.imageUrl}
            alt={selectedArtwork.title}
            className="w-full h-full object-cover"
          />
        </div>
        <div className="md:w-1/2 p-6">
          <h1 className="text-4xl font-bold text-indigo-800 mb-2">{selectedArtwork.title}</h1>
          <p className="text-xl text-gray-700 mb-4">by {selectedArtwork.artist}</p>
          <p className="text-2xl font-bold text-indigo-700 mb-4">${selectedArtwork.price.toFixed(2)}</p>
          <p className="text-gray-600 mb-4"><strong>Medium:</strong> {selectedArtwork.medium}</p>
          <p className="text-gray-800 leading-relaxed mb-6">{selectedArtwork.description}</p>

          <div className="flex items-center mb-6">
            <span className="text-xl font-semibold mr-2">Rating: {averageRating}</span>
            <span className="text-yellow-500">{[...Array(5)].map((_, i) => (
              <span key={i} className="text-xl">{i < Math.round(averageRating) ? '&#9733;' : '&#9734;'}</span>
            ))}</span>
            <span className="text-gray-600 ml-2">({reviews.length} reviews)</span>
          </div>

          <button
            onClick={handleAddToCart}
            className="w-full bg-indigo-600 text-white text-lg font-semibold py-3 px-8 rounded-md hover:bg-indigo-700 transition duration-300 shadow-md"
          >
            Add to Cart
          </button>
        </div>
      </div>

      <div className="mt-12">
        <h2 className="text-3xl font-bold text-indigo-800 mb-6">Customer Reviews</h2>
        <ReviewForm onReviewSubmit={handleReviewSubmit} />

        <div className="mt-8 space-y-6">
          {reviews.length === 0 ? (
            <p className="text-gray-600">No reviews yet. Be the first to review!</p>
          ) : (
            reviews.map((review) => (
              <div key={review.id} className="bg-white p-4 rounded-lg shadow">
                <div className="flex items-center mb-2">
                  <p className="font-bold text-lg mr-2">{review.author}</p>
                  <span className="text-yellow-500">{[...Array(5)].map((_, i) => (
                    <span key={i} className="text-lg">{i < review.rating ? '&#9733;' : '&#9734;'}</span>
                  ))}</span>
                  <p className="text-gray-500 text-sm ml-auto">{review.date}</p>
                </div>
                <p className="text-gray-700">{review.comment}</p>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default ArtworkDetails;

